package com.jaka.afkcompanion;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Starts a RuneLite client with this plugin already loaded. Used by the {@code run} Gradle task
 * and as the main class of the standalone shadow jar.
 */
public class AfkCompanionLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AfkCompanionPlugin.class);
		RuneLite.main(args);
	}
}

package com.jaka.afkcompanion.gemstonecrab;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.NPC;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GemstoneCrabTrackerTest
{
	private static final int CRAB_ID = 14779;
	private static final int SHELL_ID = 14780;
	private static final int HEALTH_SCALE = 30;

	private GemstoneCrabTracker tracker;
	private NPC crab;

	@Before
	public void setUp()
	{
		tracker = new GemstoneCrabTracker();
		crab = mock(NPC.class);
		when(crab.getId()).thenReturn(CRAB_ID);
		when(crab.getHealthScale()).thenReturn(HEALTH_SCALE);
	}

	@Test
	public void recognisesCrabAndShellById()
	{
		final NPC shell = mock(NPC.class);
		when(shell.getId()).thenReturn(SHELL_ID);

		tracker.onNpcSpawned(crab);
		assertTrue(tracker.isCrabPresent());

		tracker.onNpcSpawned(shell);
		assertTrue(tracker.isShellPresent());
		// The shell lasts 90 seconds.
		assertEquals(90, tracker.getShellSecondsLeft());
	}

	@Test
	public void firstReadingEstimatesFromTheHealthFraction()
	{
		when(crab.getHealthRatio()).thenReturn(15);

		tracker.onNpcSpawned(crab);
		tracker.onGameTick();

		// Half the bar of a ten minute cycle is roughly five minutes.
		assertEquals(300, tracker.getRemainingSeconds());
		assertFalse(tracker.isCalibrated());
	}

	@Test
	public void learnsStepLengthAndUsesItForTheEstimate()
	{
		when(crab.getHealthRatio()).thenReturn(15);
		tracker.onNpcSpawned(crab);

		// Hold at 15 for 33 ticks, which is one step of a 1000 tick cycle over 30 steps.
		for (int i = 0; i < 34; i++)
		{
			tracker.onGameTick();
		}

		when(crab.getHealthRatio()).thenReturn(14);
		tracker.onGameTick();

		assertTrue(tracker.isCalibrated());
		// 14 steps left at ~33 ticks each is ~462 ticks, or ~277 seconds.
		final int remaining = tracker.getRemainingSeconds();
		assertTrue("expected ~277s but got " + remaining, remaining > 265 && remaining < 290);
	}

	@Test
	public void keepsCountingWhileTheHealthBarIsHidden()
	{
		when(crab.getHealthRatio()).thenReturn(15);
		tracker.onNpcSpawned(crab);
		tracker.onGameTick();

		final int before = tracker.getRemainingTicks();

		// A hidden bar reports -1; the estimate should keep ticking down rather than reset.
		when(crab.getHealthRatio()).thenReturn(-1);
		tracker.onGameTick();
		tracker.onGameTick();

		assertEquals(before - 2, tracker.getRemainingTicks());
	}

	@Test
	public void countsOnlyDamageDealtToTheCrab()
	{
		final NPC other = mock(NPC.class);
		when(other.getId()).thenReturn(1234);
		when(crab.getHealthRatio()).thenReturn(20);

		tracker.onNpcSpawned(crab);
		tracker.onDamage(crab, 12);
		tracker.onDamage(other, 99);

		assertEquals(12, tracker.getDamageThisCrab());
		assertEquals(12, tracker.getDamageSession());
		assertEquals(0, tracker.getSecondsSinceLastHit());
	}

	@Test
	public void countsACrabOnlyWhenYouDamagedIt()
	{
		when(crab.getHealthRatio()).thenReturn(20);

		tracker.onNpcSpawned(crab);
		tracker.onNpcDespawned(crab);
		assertEquals(0, tracker.getCrabsCompleted());

		tracker.onNpcSpawned(crab);
		tracker.onDamage(crab, 5);
		tracker.onNpcDespawned(crab);
		assertEquals(1, tracker.getCrabsCompleted());
	}
}

package com.jaka.afkcompanion.push;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class PushSenderTest
{
	@Test
	public void wrapsBareIdsIntoMentions()
	{
		assertEquals("<@113847130>", PushSender.discordMention("113847130"));
		assertEquals("<@113847130>", PushSender.discordMention("  113847130  "));
		assertEquals("<@&987654321>", PushSender.discordMention("&987654321"));
	}

	@Test
	public void leavesReadyMadeMentionsAlone()
	{
		assertEquals("<@113847130>", PushSender.discordMention("<@113847130>"));
		assertEquals("<@&987654321>", PushSender.discordMention("<@&987654321>"));
		assertEquals("@everyone", PushSender.discordMention("@everyone"));
		assertEquals("@here", PushSender.discordMention("@here"));
		assertEquals("@everyone", PushSender.discordMention("@Everyone"));
	}

	@Test
	public void stripsTheAtPeopleCopyFromDiscord()
	{
		// Discord shows mentions as "@name", so ids get pasted with the @ still attached.
		// Passed through as typed they render as plain text and ping nobody.
		assertEquals("<@193349754950778880>", PushSender.discordMention("@193349754950778880"));
		assertEquals("<@&987654321>", PushSender.discordMention("@&987654321"));
	}

	@Test
	public void passesThroughAnythingItCannotParse()
	{
		// A username does not resolve through a webhook, but mangling it would be worse.
		assertEquals("@koks", PushSender.discordMention("@koks"));
	}

	@Test
	public void emptyMeansNoPing()
	{
		assertEquals("", PushSender.discordMention(""));
		assertEquals("", PushSender.discordMention("   "));
		assertEquals("", PushSender.discordMention(null));
	}

	@Test
	public void stripsNonAsciiFromHeaders()
	{
		// ntfy carries the text in HTTP headers when a screenshot is attached, and OkHttp
		// rejects anything outside printable ASCII.
		assertEquals("Crab burrows in 60s", PushSender.header("Crab burrows in 60s"));
		assertEquals("Skoljka  90 s", PushSender.header("Školjka \n90 s"));
	}
}

package com.jaka.afkcompanion.util;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class QuietHoursTest
{
	@Test
	public void handlesWindowInsideOneDay()
	{
		assertFalse(QuietHours.isQuiet(8, 9, 17));
		assertTrue(QuietHours.isQuiet(9, 9, 17));
		assertTrue(QuietHours.isQuiet(16, 9, 17));
		assertFalse(QuietHours.isQuiet(17, 9, 17));
	}

	@Test
	public void handlesWindowWrappingPastMidnight()
	{
		assertTrue(QuietHours.isQuiet(23, 23, 8));
		assertTrue(QuietHours.isQuiet(0, 23, 8));
		assertTrue(QuietHours.isQuiet(7, 23, 8));
		assertFalse(QuietHours.isQuiet(8, 23, 8));
		assertFalse(QuietHours.isQuiet(22, 23, 8));
	}

	@Test
	public void emptyWindowIsNeverQuiet()
	{
		// A misconfigured window must not silence every notification.
		for (int hour = 0; hour < 24; hour++)
		{
			assertFalse(QuietHours.isQuiet(hour, 12, 12));
		}
	}
}

package com.jaka.afkcompanion.util;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class FormatTest
{
	@Test
	public void formatsCoinsByMagnitude()
	{
		assertEquals("812 gp", Format.gp(812));
		assertEquals("1.0K", Format.gp(1_000));
		assertEquals("50.0K", Format.gp(50_000));
		assertEquals("2.4M", Format.gp(2_400_000));
	}

	@Test
	public void formatsDurations()
	{
		assertEquals("?", Format.time(-1));
		assertEquals("0:00", Format.time(0));
		assertEquals("0:09", Format.time(9));
		assertEquals("4:44", Format.time(284));
		assertEquals("1:00:00", Format.time(3600));
	}

	@Test
	public void formatsHourlyRates()
	{
		assertEquals("-", Format.perHour(1000, 0));
		// 10k over ten minutes is 60k an hour.
		assertEquals("60.0k/h", Format.perHour(10_000, 600));
		assertEquals("1.2m/h", Format.perHour(300_000, 900));
	}
}

package com.jaka.afkcompanion.util;

import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class NameListTest
{
	@Test
	public void parsesTrimsAndLowercases()
	{
		final Set<String> names = NameList.parse("  Shark , Prayer potion(4),, DRAGON warhammer ");
		assertEquals(3, names.size());
		assertTrue(names.contains("shark"));
		assertTrue(names.contains("prayer potion(4)"));
		assertTrue(names.contains("dragon warhammer"));
	}

	@Test
	public void blankInputIsAnEmptyList()
	{
		assertTrue(NameList.parse(null).isEmpty());
		assertTrue(NameList.parse("").isEmpty());
		assertTrue(NameList.parse("   ,  , ").isEmpty());
	}

	@Test
	public void matchesOnSubstringSoDosesAndFamiliesWork()
	{
		final Set<String> names = NameList.parse("prayer potion, dragon");

		assertEquals("prayer potion", NameList.firstMatch("Prayer potion(3)", names));
		assertEquals("dragon", NameList.firstMatch("Dragon warhammer", names));
		assertEquals("dragon", NameList.firstMatch("Uncut dragonstone", names));
	}

	@Test
	public void reportsNothingWhenItDoesNotMatch()
	{
		final Set<String> names = NameList.parse("shark");

		assertNull(NameList.firstMatch("Lobster", names));
		assertNull(NameList.firstMatch(null, names));
		assertNull(NameList.firstMatch("Shark", NameList.parse("")));
	}
}

package com.jaka.afkcompanion;

/**
 * What a notification is about. Used to decide whether a screenshot is worth attaching, so
 * that can be chosen per kind of event rather than all or nothing.
 * <p>
 * The values line up with the settings sections, so the choice reads the same way in the
 * settings panel as it does here.
 */
public enum NotificationCategory
{
	/** Gemstone Crab: burrow countdown, burrow, not landing hits. */
	CRAB,

	/** AFK safeguards: logout, hitpoints, prayer, poison, drops, random events, chat triggers. */
	AFK,

	/** Skilling and combat: idle animation, inventory, supplies, aggression, special attack. */
	SKILLING,

	/** Account events: level ups, death, Grand Exchange. */
	ACCOUNT
}

package com.jaka.afkcompanion.stats;

import com.jaka.afkcompanion.AfkCompanionConfig;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.client.config.ConfigManager;

/**
 * Session counters, plus lifetime totals that survive a restart.
 * <p>
 * Lifetime values live in the plugin's own config group under keys that have no
 * {@code @ConfigItem}, so they persist with the profile without cluttering the settings panel.
 */
@Singleton
public class SessionStats
{
	private static final String KEY_LIFETIME_CRABS = "lifetimeCrabs";
	private static final String KEY_LIFETIME_DAMAGE = "lifetimeDamage";
	private static final String KEY_LIFETIME_NOTIFICATIONS = "lifetimeNotifications";
	private static final String KEY_LIFETIME_SECONDS = "lifetimeSeconds";

	private final ConfigManager configManager;

	private Instant sessionStart = Instant.now();
	private long xpAtStart = -1;

	@Getter
	private int notifications;
	@Getter
	private int lifetimeCrabs;
	@Getter
	private long lifetimeDamage;
	@Getter
	private int lifetimeNotifications;
	@Getter
	private long lifetimeSeconds;

	private int savedCrabs;
	private long savedDamage;

	@Inject
	private SessionStats(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	public void load()
	{
		lifetimeCrabs = readInt(KEY_LIFETIME_CRABS);
		lifetimeDamage = readLong(KEY_LIFETIME_DAMAGE);
		lifetimeNotifications = readInt(KEY_LIFETIME_NOTIFICATIONS);
		lifetimeSeconds = readLong(KEY_LIFETIME_SECONDS);
	}

	public void startSession()
	{
		sessionStart = Instant.now();
		xpAtStart = -1;
		notifications = 0;
		savedCrabs = 0;
		savedDamage = 0;
	}

	public long getSessionSeconds()
	{
		return Duration.between(sessionStart, Instant.now()).getSeconds();
	}

	/**
	 * @param overallExperience the account's total XP right now
	 * @return XP gained since the session started, or 0 before the first reading
	 */
	public long getSessionXp(long overallExperience)
	{
		if (overallExperience <= 0)
		{
			return 0;
		}

		if (xpAtStart < 0)
		{
			xpAtStart = overallExperience;
			return 0;
		}

		return Math.max(0, overallExperience - xpAtStart);
	}

	public void noteNotification()
	{
		notifications++;
		lifetimeNotifications++;
	}

	/**
	 * Folds the crab tracker's running totals into the lifetime counters. Safe to call every
	 * tick: only the increase since the previous call is added.
	 */
	public void syncCrabProgress(int crabsCompleted, int sessionDamage)
	{
		if (crabsCompleted > savedCrabs)
		{
			lifetimeCrabs += crabsCompleted - savedCrabs;
			savedCrabs = crabsCompleted;
		}

		if (sessionDamage > savedDamage)
		{
			lifetimeDamage += sessionDamage - savedDamage;
			savedDamage = sessionDamage;
		}
	}

	public void save()
	{
		lifetimeSeconds += getSessionSeconds();
		sessionStart = Instant.now();

		write(KEY_LIFETIME_CRABS, lifetimeCrabs);
		write(KEY_LIFETIME_DAMAGE, lifetimeDamage);
		write(KEY_LIFETIME_NOTIFICATIONS, lifetimeNotifications);
		write(KEY_LIFETIME_SECONDS, lifetimeSeconds);
	}

	public void resetLifetime()
	{
		lifetimeCrabs = 0;
		lifetimeDamage = 0;
		lifetimeNotifications = 0;
		lifetimeSeconds = 0;
		save();
	}

	private int readInt(String key)
	{
		final Integer value = configManager.getConfiguration(AfkCompanionConfig.GROUP, key, Integer.class);
		return value == null ? 0 : value;
	}

	private long readLong(String key)
	{
		final Long value = configManager.getConfiguration(AfkCompanionConfig.GROUP, key, Long.class);
		return value == null ? 0 : value;
	}

	private void write(String key, Object value)
	{
		configManager.setConfiguration(AfkCompanionConfig.GROUP, key, value);
	}
}

package com.jaka.afkcompanion.gemstonecrab;

import com.jaka.afkcompanion.AfkCompanionConfig;
import com.jaka.afkcompanion.util.Format;
import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * Countdown infobox for the crab. Rather than being added and removed as the fight moves on,
 * it stays registered and simply declines to render when there is nothing to show.
 */
public class CrabInfoBox extends InfoBox
{
	public enum Kind
	{
		BURROW,
		SHELL
	}

	private final GemstoneCrabTracker tracker;
	private final AfkCompanionConfig config;
	private final Kind kind;

	public CrabInfoBox(BufferedImage image, Plugin plugin, GemstoneCrabTracker tracker,
		AfkCompanionConfig config, Kind kind)
	{
		super(image, plugin);
		this.tracker = tracker;
		this.config = config;
		this.kind = kind;
		setTooltip(kind == Kind.BURROW ? "Time until the Gemstone Crab burrows" : "Time left to mine the shell");
	}

	@Override
	public String getText()
	{
		return Format.time(kind == Kind.BURROW ? tracker.getRemainingSeconds() : tracker.getShellSecondsLeft());
	}

	@Override
	public Color getTextColor()
	{
		if (kind == Kind.SHELL)
		{
			return Color.ORANGE;
		}

		final int remaining = tracker.getRemainingSeconds();
		if (remaining < 0)
		{
			return Color.LIGHT_GRAY;
		}

		return remaining <= config.crabWarnSeconds() ? Color.RED : Color.WHITE;
	}

	@Override
	public boolean render()
	{
		if (!config.crabEnabled() || !config.showInfoboxes())
		{
			return false;
		}

		return kind == Kind.BURROW ? tracker.isCrabPresent() : tracker.isShellPresent();
	}
}

package com.jaka.afkcompanion.gemstonecrab;

import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.client.util.Text;

/**
 * Tracks the Gemstone Crab.
 * <p>
 * The crab's health bar does not drop from damage - it drops with time. When it empties the
 * crab burrows, sheds its shell and moves to the next of three mines, on a roughly ten minute
 * cycle. The health bar is therefore a countdown, and reading it tells us how long is left.
 * <p>
 * The bar is coarse (a few dozen steps), so instead of trusting a fixed cycle length we learn
 * how many ticks one step actually lasts and interpolate between steps. That turns a value
 * that jumps every ~20 seconds into a smooth per-second estimate.
 */
@Slf4j
@Singleton
public class GemstoneCrabTracker
{
	private static final String CRAB_NAME = "gemstone crab";
	private static final String SHELL_KEYWORD = "shell";

	/** Ids are more reliable than names; the name check stays as a fallback. */
	private static final int CRAB_ID = 14779;
	private static final int SHELL_ID = 14780;

	/** Fallback cycle length: 10 minutes, or 1000 game ticks. */
	private static final int DEFAULT_CYCLE_TICKS = 1000;

	/** The shed shell can be mined for 90 seconds, or 150 ticks. */
	private static final int SHELL_TICKS = 150;

	@Getter
	private NPC crab;
	@Getter
	private NPC shell;

	/** Estimated ticks until the crab burrows; -1 while unknown. */
	@Getter
	private int remainingTicks = -1;
	@Getter
	private int shellTicksLeft = -1;

	/** Damage you have dealt to the crab currently in the scene. */
	@Getter
	private int damageThisCrab;
	@Getter
	private int damageSession;
	@Getter
	private int crabsCompleted;
	/** Ticks since you last landed a hit on the crab; -1 if you never have. */
	@Getter
	private int ticksSinceLastHit = -1;

	private int lastRatio = -1;
	private int ticksSinceRatioChange;
	/** Learned length of one health bar step, in ticks. */
	private double stepTicks = -1;

	public boolean isCrabPresent()
	{
		return crab != null;
	}

	public boolean isShellPresent()
	{
		return shell != null && shellTicksLeft > 0;
	}

	public int getRemainingSeconds()
	{
		return remainingTicks < 0 ? -1 : (int) Math.round(remainingTicks * 0.6d);
	}

	public int getShellSecondsLeft()
	{
		return shellTicksLeft < 0 ? -1 : (int) Math.round(shellTicksLeft * 0.6d);
	}

	public int getSecondsSinceLastHit()
	{
		return ticksSinceLastHit < 0 ? -1 : (int) Math.round(ticksSinceLastHit * 0.6d);
	}

	/**
	 * @return true once the countdown has been calibrated against an observed step change
	 */
	public boolean isCalibrated()
	{
		return stepTicks > 0;
	}

	public void reset()
	{
		crab = null;
		shell = null;
		remainingTicks = -1;
		shellTicksLeft = -1;
		damageThisCrab = 0;
		ticksSinceLastHit = -1;
		lastRatio = -1;
		ticksSinceRatioChange = 0;
		stepTicks = -1;
	}

	public void resetSession()
	{
		reset();
		damageSession = 0;
		crabsCompleted = 0;
	}

	public void onNpcSpawned(NPC npc)
	{
		if (isCrab(npc))
		{
			crab = npc;
			lastRatio = -1;
			ticksSinceRatioChange = 0;
			damageThisCrab = 0;
			ticksSinceLastHit = -1;
			remainingTicks = -1;
			log.debug("Gemstone Crab spawned (id {})", npc.getId());
		}
		else if (isShell(npc))
		{
			shell = npc;
			shellTicksLeft = SHELL_TICKS;
			log.debug("Crab shell spawned (id {})", npc.getId());
		}
	}

	public void onNpcDespawned(NPC npc)
	{
		if (npc == crab)
		{
			if (damageThisCrab > 0)
			{
				crabsCompleted++;
			}
			crab = null;
			remainingTicks = 0;
			lastRatio = -1;
		}
		else if (npc == shell)
		{
			shell = null;
			shellTicksLeft = -1;
		}
	}

	public void onDamage(Actor target, int damage)
	{
		if (target != crab)
		{
			return;
		}

		if (damage > 0)
		{
			damageThisCrab += damage;
			damageSession += damage;
		}

		ticksSinceLastHit = 0;
	}

	public void onGameTick()
	{
		if (shellTicksLeft > 0)
		{
			shellTicksLeft--;
		}

		if (crab == null)
		{
			return;
		}

		if (ticksSinceLastHit >= 0)
		{
			ticksSinceLastHit++;
		}

		final int ratio = crab.getHealthRatio();
		final int scale = crab.getHealthScale();

		if (ratio < 0 || scale <= 0)
		{
			// No health bar in view (you are not in combat with it) - keep counting down
			// from the last estimate rather than throwing it away.
			if (remainingTicks > 0)
			{
				remainingTicks--;
			}
			return;
		}

		if (lastRatio < 0)
		{
			// First reading: a rough estimate straight from the fraction shown.
			lastRatio = ratio;
			ticksSinceRatioChange = 0;
			remainingTicks = (int) Math.round(ratio / (double) scale * DEFAULT_CYCLE_TICKS);
			return;
		}

		if (ratio != lastRatio)
		{
			if (ratio == lastRatio - 1 && ticksSinceRatioChange > 3)
			{
				learnStep(ticksSinceRatioChange);
			}
			lastRatio = ratio;
			ticksSinceRatioChange = 0;
			remainingTicks = (int) Math.round(ratio * stepTicks(scale));
			return;
		}

		ticksSinceRatioChange++;
		remainingTicks = Math.max(0, (int) Math.round(ratio * stepTicks(scale)) - ticksSinceRatioChange);
	}

	private double stepTicks(int scale)
	{
		if (stepTicks > 0)
		{
			return stepTicks;
		}

		return DEFAULT_CYCLE_TICKS / (double) Math.max(1, scale);
	}

	private void learnStep(int observed)
	{
		if (observed < 5 || observed > 300)
		{
			// Nonsense reading - a hop, a reload, or a bar that was hidden part of the time.
			return;
		}

		stepTicks = stepTicks < 0 ? observed : (stepTicks * 0.7d + observed * 0.3d);
		log.debug("Learned health bar step length: {} ticks", String.format("%.1f", stepTicks));
	}

	static boolean isCrab(NPC npc)
	{
		if (npc == null)
		{
			return false;
		}

		if (npc.getId() == CRAB_ID)
		{
			return true;
		}

		final String name = name(npc);
		return name.contains(CRAB_NAME) && !name.contains(SHELL_KEYWORD);
	}

	static boolean isShell(NPC npc)
	{
		if (npc == null)
		{
			return false;
		}

		if (npc.getId() == SHELL_ID)
		{
			return true;
		}

		final String name = name(npc);
		return name.contains(CRAB_NAME) && name.contains(SHELL_KEYWORD);
	}

	private static String name(NPC npc)
	{
		final String name = npc == null ? null : npc.getName();
		return name == null ? "" : Text.standardize(name);
	}
}

package com.jaka.afkcompanion.gemstonecrab;

import com.jaka.afkcompanion.AfkCompanionConfig;
import com.jaka.afkcompanion.util.Format;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class GemstoneCrabOverlay extends OverlayPanel
{
	private static final Color ACCENT = new Color(0x8A, 0xC7, 0xDB);

	private final GemstoneCrabTracker tracker;
	private final AfkCompanionConfig config;

	@Inject
	GemstoneCrabOverlay(GemstoneCrabTracker tracker, AfkCompanionConfig config)
	{
		this.tracker = tracker;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(150, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.crabEnabled() || !config.crabOverlay())
		{
			return null;
		}

		final boolean crab = tracker.isCrabPresent();
		final boolean shell = tracker.isShellPresent();

		if (!crab && !shell)
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Gemstone Crab")
			.color(ACCENT)
			.build());

		if (crab)
		{
			final int remaining = tracker.getRemainingSeconds();
			final Color color = remaining < 0
				? Color.LIGHT_GRAY
				: remaining <= config.crabWarnSeconds() ? Color.RED : Color.GREEN;

			panelComponent.getChildren().add(LineComponent.builder()
				.left("Burrows in")
				.right(Format.time(remaining) + (tracker.isCalibrated() ? "" : "?"))
				.rightColor(color)
				.build());

			panelComponent.getChildren().add(LineComponent.builder()
				.left("Your damage")
				.right(String.valueOf(tracker.getDamageThisCrab()))
				.build());

			final int sinceHit = tracker.getSecondsSinceLastHit();
			if (sinceHit >= 5)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Not hitting")
					.right(Format.time(sinceHit))
					.rightColor(sinceHit >= config.crabIdleSeconds() ? Color.RED : Color.YELLOW)
					.build());
			}
		}

		if (shell)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Shell")
				.right(Format.time(tracker.getShellSecondsLeft()))
				.rightColor(Color.ORANGE)
				.build());
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Session")
			.right(tracker.getCrabsCompleted() + " crab / " + tracker.getDamageSession() + " dmg")
			.rightColor(Color.LIGHT_GRAY)
			.build());

		return super.render(graphics);
	}
}

package com.jaka.afkcompanion;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayDeque;
import java.util.Deque;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel: live status, session and lifetime totals, a delivery test button and a log of
 * the notifications this session has produced.
 */
@Singleton
public class AfkCompanionPanel extends PluginPanel
{
	private static final int HISTORY_SIZE = 12;
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm:ss");

	private final JLabel serviceValue = value();
	private final JLabel controlValue = value();
	private final JLabel crabValue = value();
	private final JLabel shellValue = value();
	private final JLabel sessionValue = value();
	private final JLabel xpValue = value();
	private final JLabel sentValue = value();
	private final JLabel lifetimeCrabsValue = value();
	private final JLabel lifetimeSentValue = value();

	private final JPanel historyPanel = new JPanel();
	private final Deque<String> history = new ArrayDeque<>();

	private Runnable onTest = () ->
	{
	};
	private Runnable onResetSession = () ->
	{
	};

	@Inject
	private AfkCompanionPanel()
	{
		super(false);

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		content.add(header("Status"));
		content.add(rows(
			"Service", serviceValue,
			"Control", controlValue,
			"Burrows in", crabValue,
			"Shell", shellValue));

		content.add(spacer());
		content.add(header("Session"));
		content.add(rows(
			"Time", sessionValue,
			"XP", xpValue,
			"Sent", sentValue));

		content.add(spacer());
		content.add(header("All time"));
		content.add(rows(
			"Crabs", lifetimeCrabsValue,
			"Notifications", lifetimeSentValue));

		content.add(spacer());
		content.add(button("Send test notification", () -> onTest.run()));
		content.add(button("Reset session", () -> onResetSession.run()));

		content.add(spacer());
		content.add(header("Recent notifications"));
		historyPanel.setLayout(new BoxLayout(historyPanel, BoxLayout.Y_AXIS));
		historyPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		historyPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(historyPanel);

		add(content, BorderLayout.NORTH);
		renderHistory();
	}

	public void setActions(Runnable onTest, Runnable onResetSession)
	{
		this.onTest = onTest;
		this.onResetSession = onResetSession;
	}

	/**
	 * Called from the client thread; all Swing work is pushed to the EDT.
	 */
	public void update(String service, String control, String burrow, String shell,
		String session, String xp, String sent, String lifetimeCrabs, String lifetimeSent)
	{
		SwingUtilities.invokeLater(() ->
		{
			serviceValue.setText(service);
			controlValue.setText(control);
			crabValue.setText(burrow);
			shellValue.setText(shell);
			sessionValue.setText(session);
			xpValue.setText(xp);
			sentValue.setText(sent);
			lifetimeCrabsValue.setText(lifetimeCrabs);
			lifetimeSentValue.setText(lifetimeSent);
		});
	}

	public void addHistory(String title, String message)
	{
		final String line = LocalTime.now().format(CLOCK) + "  " + title + " - " + message;

		SwingUtilities.invokeLater(() ->
		{
			history.addFirst(line);
			while (history.size() > HISTORY_SIZE)
			{
				history.removeLast();
			}
			renderHistory();
		});
	}

	public void clearHistory()
	{
		SwingUtilities.invokeLater(() ->
		{
			history.clear();
			renderHistory();
		});
	}

	private void renderHistory()
	{
		historyPanel.removeAll();

		if (history.isEmpty())
		{
			historyPanel.add(note("Nothing yet this session."));
		}
		else
		{
			for (String line : history)
			{
				historyPanel.add(note(line));
			}
		}

		historyPanel.revalidate();
		historyPanel.repaint();
	}

	private static JLabel header(String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(ColorScheme.BRAND_ORANGE);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		return label;
	}

	private static JLabel value()
	{
		final JLabel label = new JLabel("-");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return label;
	}

	private static JLabel note(String text)
	{
		// HTML wrapping keeps long notification text inside the narrow side panel.
		final JLabel label = new JLabel("<html><body style='width:150px'>" + escape(text) + "</body></html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 3, 0));
		return label;
	}

	private JPanel rows(Object... labelsAndValues)
	{
		final JPanel panel = new JPanel(new GridLayout(labelsAndValues.length / 2, 2, 4, 2));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		for (int i = 0; i < labelsAndValues.length; i += 2)
		{
			final JLabel key = new JLabel((String) labelsAndValues[i]);
			key.setFont(FontManager.getRunescapeSmallFont());
			key.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
			panel.add(key);
			panel.add((JLabel) labelsAndValues[i + 1]);
		}

		return panel;
	}

	private static JButton button(String text, Runnable action)
	{
		final JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		button.addActionListener(e -> action.run());
		return button;
	}

	private static Component spacer()
	{
		final JPanel panel = new JPanel();
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 10));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);
		return panel;
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.jaka.afkcompanion.push;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.jaka.afkcompanion.AfkCompanionConfig;
import java.util.Locale;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

/**
 * Listens on an ntfy topic so you can ask the client a question from your phone.
 * <p>
 * This is deliberately read-only: commands can request information, never perform an
 * action in the game. Anyone who knows the control topic can query it, which is why it
 * is opt-in and documented as such.
 */
@Slf4j
@Singleton
public class NtfyControl
{
	private static final int RETRY_MIN_SECONDS = 5;
	private static final int RETRY_MAX_SECONDS = 300;

	private final OkHttpClient httpClient;
	private final AfkCompanionConfig config;
	private final ScheduledExecutorService executor;
	private final Gson gson;

	private WebSocket socket;
	private Consumer<String> commandHandler;
	private volatile boolean running;
	private volatile boolean connected;
	private int retrySeconds = RETRY_MIN_SECONDS;

	@Inject
	private NtfyControl(OkHttpClient httpClient, AfkCompanionConfig config,
		ScheduledExecutorService executor, Gson gson)
	{
		this.httpClient = httpClient;
		this.config = config;
		this.executor = executor;
		this.gson = gson;
	}

	public boolean isConnected()
	{
		return connected;
	}

	public boolean isEnabled()
	{
		return config.sendNtfy() && !controlTopic().isEmpty();
	}

	public synchronized void start(Consumer<String> handler)
	{
		this.commandHandler = handler;

		if (running)
		{
			return;
		}

		if (!isEnabled())
		{
			return;
		}

		running = true;
		retrySeconds = RETRY_MIN_SECONDS;
		connect();
	}

	public synchronized void stop()
	{
		running = false;
		connected = false;

		if (socket != null)
		{
			socket.close(1000, "plugin stopped");
			socket = null;
		}
	}

	/**
	 * Re-reads the configuration and reconnects if the topic changed.
	 */
	public synchronized void restart()
	{
		final Consumer<String> handler = commandHandler;
		stop();

		if (handler != null && isEnabled())
		{
			start(handler);
		}
	}

	private synchronized void connect()
	{
		if (!running)
		{
			return;
		}

		final HttpUrl base = HttpUrl.parse(server());
		if (base == null)
		{
			log.warn("ntfy server is not a valid URL, control channel disabled");
			running = false;
			return;
		}

		// OkHttp performs the WebSocket upgrade itself, so an http(s) URL is what it wants here.
		final HttpUrl url = base.newBuilder()
			.addPathSegment(controlTopic())
			.addPathSegment("ws")
			.build();

		log.debug("Opening ntfy control channel on {}", url);
		socket = httpClient.newWebSocket(new Request.Builder().url(url).build(), new Listener());
	}

	private void scheduleReconnect()
	{
		if (!running)
		{
			return;
		}

		final int delay = retrySeconds;
		retrySeconds = Math.min(RETRY_MAX_SECONDS, retrySeconds * 2);
		log.debug("Reconnecting to ntfy control channel in {}s", delay);
		executor.schedule(this::connect, delay, TimeUnit.SECONDS);
	}

	private String server()
	{
		final String server = config.ntfyServer() == null ? "" : config.ntfyServer().trim();
		return server.isEmpty() ? "https://ntfy.sh" : server;
	}

	private String controlTopic()
	{
		return config.ntfyControlTopic() == null ? "" : config.ntfyControlTopic().trim();
	}

	private class Listener extends WebSocketListener
	{
		@Override
		public void onOpen(WebSocket webSocket, Response response)
		{
			connected = true;
			retrySeconds = RETRY_MIN_SECONDS;
			log.debug("ntfy control channel open");
			response.close();
		}

		@Override
		public void onMessage(WebSocket webSocket, String text)
		{
			final String command = parseCommand(text);
			if (command == null || command.isEmpty())
			{
				return;
			}

			final Consumer<String> handler = commandHandler;
			if (handler != null)
			{
				handler.accept(command);
			}
		}

		@Override
		public void onFailure(WebSocket webSocket, Throwable t, Response response)
		{
			connected = false;
			if (response != null)
			{
				response.close();
			}

			if (running)
			{
				log.debug("ntfy control channel dropped: {}", t.getMessage());
				scheduleReconnect();
			}
		}

		@Override
		public void onClosed(WebSocket webSocket, int code, String reason)
		{
			connected = false;
			if (running)
			{
				scheduleReconnect();
			}
		}
	}

	/**
	 * ntfy streams one JSON object per frame; only "message" events carry user text.
	 */
	private String parseCommand(String frame)
	{
		try
		{
			final JsonObject json = gson.fromJson(frame, JsonObject.class);
			if (json == null || !json.has("event"))
			{
				return null;
			}

			if (!"message".equals(json.get("event").getAsString()) || !json.has("message"))
			{
				return null;
			}

			return json.get("message").getAsString().trim().toLowerCase(Locale.ROOT);
		}
		catch (JsonParseException | IllegalStateException | UnsupportedOperationException e)
		{
			log.debug("Unparseable ntfy frame: {}", e.getMessage());
			return null;
		}
	}
}

package com.jaka.afkcompanion.push;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.jaka.afkcompanion.AfkCompanionConfig;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.text.Normalizer;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.FormBody;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Delivers a notification to the configured phone service.
 * <p>
 * Everything past the cooldown check - PNG encoding included - happens off the client
 * thread, so a slow or unreachable service can never stutter the game.
 */
@Slf4j
@Singleton
public class PushSender
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final MediaType PNG = MediaType.parse("image/png");
	private static final String SCREENSHOT_NAME = "osrs.png";

	/** At or above this priority a notification counts as urgent. */
	private static final int URGENT_PRIORITY = 5;

	/** Discord embed accent, by notification priority. */
	private static final int COLOR_URGENT = 0xE03D3D;
	private static final int COLOR_NORMAL = 0xF2B038;
	private static final int COLOR_LOW = 0x5865F2;

	private final OkHttpClient httpClient;
	private final AfkCompanionConfig config;
	private final ScheduledExecutorService executor;

	private long lastSentAt;
	private int sentCount;
	private int failedCount;

	@Inject
	private PushSender(OkHttpClient httpClient, AfkCompanionConfig config, ScheduledExecutorService executor)
	{
		this.httpClient = httpClient;
		this.config = config;
		this.executor = executor;
	}

	public void resetCooldown()
	{
		lastSentAt = 0;
	}

	public int getSentCount()
	{
		return sentCount;
	}

	public int getFailedCount()
	{
		return failedCount;
	}

	public void resetCounters()
	{
		sentCount = 0;
		failedCount = 0;
	}

	/**
	 * @return every delivery target the user has switched on
	 */
	public List<PushProvider> enabledProviders()
	{
		final List<PushProvider> providers = new ArrayList<>();

		if (config.sendNtfy())
		{
			providers.add(PushProvider.NTFY);
		}
		if (config.sendDiscord())
		{
			providers.add(PushProvider.DISCORD);
		}
		if (config.sendPushover())
		{
			providers.add(PushProvider.PUSHOVER);
		}
		if (config.sendTelegram())
		{
			providers.add(PushProvider.TELEGRAM);
		}
		if (config.sendWebhook())
		{
			providers.add(PushProvider.WEBHOOK);
		}

		return providers;
	}

	public boolean hasAnyProvider()
	{
		return !enabledProviders().isEmpty();
	}

	/**
	 * @return true if at least one enabled target can carry an image
	 */
	public boolean anySupportsScreenshots()
	{
		return enabledProviders().stream().anyMatch(PushProvider::supportsScreenshots);
	}

	/**
	 * @return the enabled targets as a short label, e.g. "ntfy + Discord"
	 */
	public String enabledLabel()
	{
		final List<PushProvider> providers = enabledProviders();
		return providers.isEmpty()
			? "off"
			: providers.stream().map(PushProvider::toString).collect(Collectors.joining(" + "));
	}

	public boolean send(String title, String message, int priority)
	{
		return send(title, message, priority, null);
	}

	/**
	 * @param screenshot image to attach (ntfy and Discord only), or null
	 * @return true if the notification was accepted for delivery by at least one target
	 */
	public boolean send(String title, String message, int priority, BufferedImage screenshot)
	{
		return send(title, message, priority, screenshot, null);
	}

	/**
	 * Delivers to every enabled target. A target that is switched on but not configured is
	 * skipped with a warning rather than blocking the others.
	 *
	 * @param onResult optional callback receiving one human-readable result per target
	 */
	public boolean send(String title, String message, int priority, BufferedImage screenshot, Consumer<String> onResult)
	{
		final List<PushProvider> providers = usableProviders(onResult);
		if (providers.isEmpty())
		{
			return false;
		}

		final long now = System.currentTimeMillis();
		final long cooldownMs = config.pushCooldownSeconds() * 1000L;
		if (lastSentAt != 0 && now - lastSentAt < cooldownMs)
		{
			log.debug("Push suppressed by cooldown: {}", title);
			return false;
		}

		lastSentAt = now;
		executor.execute(() -> dispatchAll(providers, title, message, priority, screenshot, onResult));
		return true;
	}

	/**
	 * Sends without touching the shared cooldown. Used for replies to a command from the phone,
	 * which the user explicitly asked for and should never be silently dropped.
	 */
	public void sendImmediate(String title, String message, int priority)
	{
		final List<PushProvider> providers = usableProviders(null);
		if (providers.isEmpty())
		{
			return;
		}

		executor.execute(() -> dispatchAll(providers, title, message, priority, null, null));
	}

	private List<PushProvider> usableProviders(Consumer<String> onResult)
	{
		final List<PushProvider> usable = new ArrayList<>();

		for (PushProvider provider : enabledProviders())
		{
			try
			{
				checkConfigured(provider);
				usable.add(provider);
			}
			catch (IllegalArgumentException e)
			{
				log.warn("{} is enabled but not configured: {}", provider, e.getMessage());
				report(onResult, provider + ": " + e.getMessage());
			}
		}

		return usable;
	}

	private void dispatchAll(List<PushProvider> providers, String title, String message, int priority,
		BufferedImage screenshot, Consumer<String> onResult)
	{
		// Encoded once and shared, however many targets are enabled.
		final byte[] png = encode(screenshot);

		for (PushProvider provider : providers)
		{
			dispatch(provider, title, message, priority, png, onResult);
		}
	}

	private void dispatch(PushProvider provider, String title, String message, int priority,
		byte[] png, Consumer<String> onResult)
	{
		final Request request;
		try
		{
			request = buildRequest(provider, title, message, priority,
				provider.supportsScreenshots() ? png : null);
		}
		catch (IllegalArgumentException e)
		{
			log.warn("{} is not configured: {}", provider, e.getMessage());
			report(onResult, provider + ": " + e.getMessage());
			return;
		}

		if (request == null)
		{
			return;
		}

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				failedCount++;
				log.warn("Push notification to {} failed", provider, e);
				report(onResult, provider + ": failed, " + e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				if (response.isSuccessful())
				{
					sentCount++;
					report(onResult, provider + ": delivered");
				}
				else
				{
					failedCount++;
					log.warn("Push notification to {} rejected: HTTP {}", provider, response.code());
					report(onResult, provider + ": rejected with HTTP " + response.code());
				}
				response.close();
			}
		});
	}

	private static void report(Consumer<String> onResult, String result)
	{
		if (onResult != null)
		{
			onResult.accept(result);
		}
	}

	private byte[] encode(BufferedImage image)
	{
		if (image == null)
		{
			return null;
		}

		try (ByteArrayOutputStream out = new ByteArrayOutputStream())
		{
			ImageIO.write(image, "png", out);
			return out.toByteArray();
		}
		catch (IOException e)
		{
			log.warn("Could not encode the screenshot", e);
			return null;
		}
	}

	private void checkConfigured(PushProvider provider)
	{
		switch (provider)
		{
			case NTFY:
				require(trimmed(config.ntfyTopic()), "ntfy topic is empty");
				break;
			case DISCORD:
				require(trimmed(config.discordWebhookUrl()), "Discord webhook URL is empty");
				break;
			case PUSHOVER:
				require(trimmed(config.pushoverAppToken()), "Pushover app token is empty");
				require(trimmed(config.pushoverUserKey()), "Pushover user key is empty");
				break;
			case TELEGRAM:
				require(trimmed(config.telegramBotToken()), "Telegram bot token is empty");
				require(trimmed(config.telegramChatId()), "Telegram chat id is empty");
				break;
			case WEBHOOK:
				require(trimmed(config.webhookUrl()), "Webhook URL is empty");
				break;
			default:
				break;
		}
	}

	private Request buildRequest(PushProvider provider, String title, String message, int priority, byte[] png)
	{
		switch (provider)
		{
			case NTFY:
				return ntfyRequest(title, message, priority, png);
			case DISCORD:
				return discordRequest(title, message, priority, png);
			case PUSHOVER:
				return pushoverRequest(title, message, priority);
			case TELEGRAM:
				return telegramRequest(title, message);
			case WEBHOOK:
				return webhookRequest(title, message, priority);
			default:
				return null;
		}
	}

	private Request ntfyRequest(String title, String message, int priority, byte[] png)
	{
		final String topic = trimmed(config.ntfyTopic());
		final HttpUrl base = ntfyBaseUrl();
		final int prio = clamp(priority, 1, 5);

		if (png != null)
		{
			// With an attachment the body is the image itself, so the text moves into
			// headers - and those must be plain ASCII.
			return new Request.Builder()
				.url(base.newBuilder().addPathSegment(topic).build())
				.addHeader("Title", header(title))
				.addHeader("Message", header(message))
				.addHeader("Priority", String.valueOf(prio))
				.addHeader("Tags", "crab")
				.addHeader("Filename", SCREENSHOT_NAME)
				.post(RequestBody.create(PNG, png))
				.build();
		}

		final JsonObject body = new JsonObject();
		body.addProperty("topic", topic);
		body.addProperty("title", title);
		body.addProperty("message", message);
		// ntfy priorities run 1 (min) to 5 (max).
		body.addProperty("priority", prio);
		final JsonArray tags = new JsonArray();
		tags.add("crab");
		body.add("tags", tags);

		return new Request.Builder()
			.url(base)
			.post(RequestBody.create(JSON, body.toString()))
			.build();
	}

	HttpUrl ntfyBaseUrl()
	{
		final String server = defaultIfBlank(trimmed(config.ntfyServer()), "https://ntfy.sh");
		final HttpUrl base = HttpUrl.parse(server);
		require(base, "ntfy server is not a valid URL");
		return base;
	}

	private Request discordRequest(String title, String message, int priority, byte[] png)
	{
		final HttpUrl url = HttpUrl.parse(trimmed(config.discordWebhookUrl()));
		require(url, "Discord webhook URL is not valid");

		final JsonObject embed = new JsonObject();
		embed.addProperty("title", title);
		embed.addProperty("description", message);
		embed.addProperty("color", priority >= 5 ? COLOR_URGENT : priority >= 4 ? COLOR_NORMAL : COLOR_LOW);

		if (png != null)
		{
			final JsonObject image = new JsonObject();
			image.addProperty("url", "attachment://" + SCREENSHOT_NAME);
			embed.add("image", image);
		}

		final JsonArray embeds = new JsonArray();
		embeds.add(embed);

		final JsonObject payload = new JsonObject();
		payload.addProperty("username", "AFK Companion");
		payload.add("embeds", embeds);

		// Discord only pings for mentions in the message content - one inside an embed is
		// rendered but never notifies anyone.
		if (!config.discordMentionUrgentOnly() || priority >= URGENT_PRIORITY)
		{
			final String mention = discordMention(config.discordMention());
			if (!mention.isEmpty())
			{
				payload.addProperty("content", mention);

				final JsonArray parse = new JsonArray();
				parse.add("users");
				parse.add("roles");
				parse.add("everyone");
				final JsonObject allowed = new JsonObject();
				allowed.add("parse", parse);
				payload.add("allowed_mentions", allowed);
			}
		}

		if (png != null)
		{
			final MultipartBody body = new MultipartBody.Builder()
				.setType(MultipartBody.FORM)
				.addFormDataPart("payload_json", payload.toString())
				.addFormDataPart("files[0]", SCREENSHOT_NAME, RequestBody.create(PNG, png))
				.build();

			return new Request.Builder().url(url).post(body).build();
		}

		return new Request.Builder()
			.url(url)
			.post(RequestBody.create(JSON, payload.toString()))
			.build();
	}

	private Request pushoverRequest(String title, String message, int priority)
	{
		final FormBody body = new FormBody.Builder()
			.add("token", trimmed(config.pushoverAppToken()))
			.add("user", trimmed(config.pushoverUserKey()))
			.add("title", title)
			.add("message", message)
			// Pushover priorities run -2 to 2; 2 needs a retry/expiry pair, so we stop at 1.
			.add("priority", String.valueOf(clamp(priority - 3, -2, 1)))
			.build();

		return new Request.Builder()
			.url("https://api.pushover.net/1/messages.json")
			.post(body)
			.build();
	}

	private Request telegramRequest(String title, String message)
	{
		final FormBody body = new FormBody.Builder()
			.add("chat_id", trimmed(config.telegramChatId()))
			.add("text", title + "\n" + message)
			.build();

		return new Request.Builder()
			.url("https://api.telegram.org/bot" + trimmed(config.telegramBotToken()) + "/sendMessage")
			.post(body)
			.build();
	}

	private Request webhookRequest(String title, String message, int priority)
	{
		final HttpUrl url = HttpUrl.parse(trimmed(config.webhookUrl()));
		require(url, "Webhook URL is not valid");

		final JsonObject body = new JsonObject();
		body.addProperty("source", "afk-companion");
		body.addProperty("title", title);
		body.addProperty("message", message);
		body.addProperty("priority", priority);

		return new Request.Builder()
			.url(url)
			.post(RequestBody.create(JSON, body.toString()))
			.build();
	}

	/**
	 * Turns whatever the user typed into something Discord will actually ping.
	 * Accepts a bare user id, a role id prefixed with {@code &}, an already formed
	 * {@code <@...>} mention, or {@code @everyone} / {@code @here}.
	 *
	 * @return the mention to put in the message content, or an empty string for no ping
	 */
	static String discordMention(String raw)
	{
		final String trimmed = raw == null ? "" : raw.trim();

		if (trimmed.isEmpty() || trimmed.startsWith("<@"))
		{
			return trimmed;
		}

		if (trimmed.equalsIgnoreCase("@everyone") || trimmed.equalsIgnoreCase("@here"))
		{
			return trimmed.toLowerCase(Locale.ROOT);
		}

		// Discord displays mentions as "@name", so an id is very often pasted with the @ still
		// on it. Left as typed it renders as plain text and pings nobody, so drop it here.
		final String id = trimmed.startsWith("@") ? trimmed.substring(1) : trimmed;

		if (id.startsWith("&") && id.substring(1).matches("\\d+"))
		{
			return "<@&" + id.substring(1) + ">";
		}

		if (id.matches("\\d+"))
		{
			return "<@" + id + ">";
		}

		// Anything else is passed through untouched rather than mangled into a broken mention.
		return trimmed;
	}

	/**
	 * HTTP headers may only carry printable ASCII, and never a line break.
	 */
	static String header(String value)
	{
		if (value == null)
		{
			return "";
		}

		// Decomposing first means an accented letter degrades to its base letter rather than
		// vanishing, so "Skoljka" survives where a blind ASCII filter would leave "koljka".
		final String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
		final StringBuilder sb = new StringBuilder(decomposed.length());

		for (char c : decomposed.toCharArray())
		{
			if (Character.getType(c) == Character.NON_SPACING_MARK)
			{
				continue;
			}

			sb.append(c >= 32 && c < 127 ? c : ' ');
		}

		return sb.toString().trim();
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}

	private static void require(Object value, String error)
	{
		if (value == null || (value instanceof String && ((String) value).isEmpty()))
		{
			throw new IllegalArgumentException(error);
		}
	}

	private static String trimmed(String value)
	{
		return value == null ? "" : value.trim();
	}

	private static String defaultIfBlank(String value, String fallback)
	{
		return value.isEmpty() ? fallback : value;
	}
}

package com.jaka.afkcompanion.push;

/**
 * A delivery target. Several can be enabled at once, in which case every notification goes
 * to all of them.
 */
public enum PushProvider
{
	NTFY("ntfy"),
	DISCORD("Discord"),
	PUSHOVER("Pushover"),
